import{_ as r,a8 as l,o,c as n,ah as s,K as e}from"./chunks/framework.BPpifGc1.js";import"./chunks/theme.e9TzJunN.js";const P=JSON.parse('{"title":"摄影","description":"","frontmatter":{"tags":["life","photography"]},"headers":[],"relativePath":"vault/笔记/🌱 生活/摄影.md","filePath":"vault/笔记/🌱 生活/摄影.md","lastUpdated":1784174736000}'),p={name:"vault/笔记/🌱 生活/摄影.md"};function h(d,a,m,c,_,u){const i=l("NolebaseGitContributors"),t=l("NolebaseGitChangelog");return o(),n("div",null,[a[0]||(a[0]=s('<h1 id="摄影" tabindex="-1">摄影 <a class="header-anchor" href="#摄影" aria-label="Permalink to “摄影”">​</a></h1><h2 id="焦段" tabindex="-1">焦段 <a class="header-anchor" href="#焦段" aria-label="Permalink to “焦段”">​</a></h2><h3 id="广角" tabindex="-1">广角 <a class="header-anchor" href="#广角" aria-label="Permalink to “广角”">​</a></h3><p>10 mm - 35 mm</p><p>好处：</p><ul><li>显腿长</li><li>近距离也能让画面有更多元素</li><li>低角度仰拍</li><li>强化线条纵深感</li><li>拍出互动感</li><li>加强空间感</li><li>视觉张力</li></ul><p>注意点：</p><ul><li>不能讲人物头部放到最前面，需要一些前景</li><li>尽量拍全身或大半身</li><li>拍人像时，人物尽量放中央</li></ul><h3 id="标准" tabindex="-1">标准 <a class="header-anchor" href="#标准" aria-label="Permalink to “标准”">​</a></h3><p>40 mm - 60 mm</p><p>好处：</p><ul><li>接近人眼观看</li><li>不出现畸变</li><li>拍出互动感</li><li>男友视角</li><li>把脸拍好看</li><li>能胜任大部分景别</li><li>脚贴近画面边缘，头顶留空</li></ul><p>弊端：</p><ul><li>拍出来视角平淡</li></ul><h3 id="中长焦" tabindex="-1">中长焦 <a class="header-anchor" href="#中长焦" aria-label="Permalink to “中长焦”">​</a></h3><p>85 mm - 135 mm</p><p>场景：特写，中近景必备</p><p>特定：空间压缩个，背景虚化</p><p>好处：</p><ul><li>拍局部特写，边缘不会畸变</li><li>只拍摄想让观众看到的那部分，让画面更简洁</li></ul><h3 id="长焦" tabindex="-1">长焦 <a class="header-anchor" href="#长焦" aria-label="Permalink to “长焦”">​</a></h3><p>长焦拍大场景能拍出人景合一的效果，场景元素在画面中充分展示，把主体放在画面上合适的位置即可</p>',22)),e(i),e(t)])}const x=r(p,[["render",h]]);export{P as __pageData,x as default};
